//! Installable toolchains: the catalog of known releases (URL, size, sha256), embedded in the
//! binary and generated by `cargo xtask catalog` (M3, M4), and of the GCC source releases cxvm
//! can build with the libraries they need (M5). `CXVM_CATALOG` points at another file with the
//! same format, for tests and mirrors.

use std::path::{Path, PathBuf};

use serde::Deserialize;

use crate::error::{Error, Result};
use crate::files;
use crate::toolchain::{Kind, Spec, ToolchainId};

/// Environment variable naming a catalog file to use instead of the embedded one.
pub const ENV_VAR: &str = "CXVM_CATALOG";

/// The catalog files built into cxvm.
const EMBEDDED: [&str; 3] = [
    include_str!("../catalog/clang.toml"),
    include_str!("../catalog/gcc.toml"),
    include_str!("../catalog/gcc-source.toml"),
];

/// A file to download: its name in the download cache, where it is, and what it must be.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Download<'a> {
    pub asset: &'a str,
    pub url: &'a str,
    /// Size in bytes.
    pub size: u64,
    /// Lowercase hex sha256.
    pub sha256: &'a str,
}

/// One installable release.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Release {
    pub id: ToolchainId,
    /// File name of the archive, also its name in the download cache.
    pub asset: String,
    pub url: String,
    /// Archive size in bytes.
    pub size: u64,
    /// Lowercase hex sha256 of the archive.
    pub sha256: String,
    /// Where the checksum comes from, e.g. `attestation` (see docs/backends.md).
    pub source: String,
}

impl Release {
    /// The archive to download.
    pub fn download(&self) -> Download<'_> {
        Download {
            asset: &self.asset,
            url: &self.url,
            size: self.size,
            sha256: &self.sha256,
        }
    }
}

/// A library tarball GCC is built with (GMP, MPFR, MPC, ISL), as named by the
/// `contrib/download_prerequisites` of GCC's source tree.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Prerequisite {
    /// File name, e.g. `gmp-6.1.0.tar.bz2`.
    pub asset: String,
    pub url: String,
    pub size: u64,
    pub sha256: String,
    pub source: String,
}

impl Prerequisite {
    /// The tarball to download.
    pub fn download(&self) -> Download<'_> {
        Download {
            asset: &self.asset,
            url: &self.url,
            size: self.size,
            sha256: &self.sha256,
        }
    }
}

/// The installable releases, sorted by id.
#[derive(Debug, Clone)]
pub struct Catalog {
    /// Prebuilt archives.
    releases: Vec<Release>,
    /// GCC source tarballs, built with `cxvm install --from-source`.
    source_releases: Vec<Release>,
    prerequisites: Vec<Prerequisite>,
    /// The `CXVM_CATALOG` file, or `None` for the embedded catalog.
    origin: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawCatalog {
    #[serde(default)]
    clang: Vec<RawRelease>,
    #[serde(default)]
    gcc: Vec<RawRelease>,
    #[serde(default, rename = "gcc-source")]
    gcc_source: Vec<RawRelease>,
    #[serde(default)]
    prerequisite: Vec<RawPrerequisite>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawRelease {
    version: String,
    asset: String,
    url: String,
    size: u64,
    sha256: String,
    source: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawPrerequisite {
    asset: String,
    url: String,
    size: u64,
    sha256: String,
    source: String,
}

const HINT: &str = "fix the file, or unset CXVM_CATALOG to use the catalog built into cxvm";

impl Catalog {
    /// The catalog built into cxvm.
    pub fn embedded() -> Self {
        let mut merged = Self {
            releases: Vec::new(),
            source_releases: Vec::new(),
            prerequisites: Vec::new(),
            origin: None,
        };
        for text in EMBEDDED {
            let catalog = Self::parse(text, None).expect("the embedded catalog is valid");
            merged.releases.extend(catalog.releases);
            merged.source_releases.extend(catalog.source_releases);
            merged.prerequisites.extend(catalog.prerequisites);
        }
        merged.releases.sort_by(|a, b| a.id.cmp(&b.id));
        merged.source_releases.sort_by(|a, b| a.id.cmp(&b.id));
        merged
    }

    /// The catalog in `path` (from `CXVM_CATALOG`), or the embedded one.
    pub fn load(path: Option<&Path>) -> Result<Self> {
        let Some(path) = path else {
            return Ok(Self::embedded());
        };
        let text = std::fs::read_to_string(path).map_err(|source| Error::Io {
            action: "read",
            path: path.to_owned(),
            source,
            hint: "point CXVM_CATALOG at a readable catalog file, or unset it",
        })?;
        Self::parse(&text, Some(path))
    }

    fn parse(text: &str, path: Option<&Path>) -> Result<Self> {
        let invalid = |message: String| Error::InvalidFile {
            path: path.map_or_else(|| "the built-in catalog".into(), Path::to_owned),
            message,
            hint: HINT.into(),
        };
        let raw: RawCatalog =
            toml::from_str(text).map_err(|err| invalid(err.to_string().trim_end().to_owned()))?;
        // What every downloaded file must have, whatever it is.
        let check = |what: &str, asset: &str, url: &str, sha256: &str| {
            if !files::is_plain_file_name(asset) {
                return Err(invalid(format!(
                    "{what}: asset `{asset}` is not a plain file name"
                )));
            }
            if !(url.starts_with("https://") || url.starts_with("http://")) {
                return Err(invalid(format!("{what}: url `{url}` is not http(s)")));
            }
            if !is_sha256(sha256) {
                return Err(invalid(format!(
                    "{what}: sha256 `{sha256}` is not 64 lowercase hex digits"
                )));
            }
            Ok(())
        };
        let parse_releases = |entries: Vec<(Kind, RawRelease)>, from_source: bool| {
            let mut releases: Vec<Release> = Vec::new();
            for (kind, entry) in entries {
                let id = format!("{kind}@{}", entry.version)
                    .parse::<ToolchainId>()
                    .ok()
                    .filter(|id| id.version().suffix().is_none())
                    .ok_or_else(|| {
                        invalid(format!("`{}` is not an x.y.z version", entry.version))
                    })?;
                let what = if from_source {
                    format!("{id} (source)")
                } else {
                    id.to_string()
                };
                if releases.iter().any(|r| r.id == id) {
                    return Err(invalid(format!("{what} is listed twice")));
                }
                check(&what, &entry.asset, &entry.url, &entry.sha256)?;
                releases.push(Release {
                    id,
                    asset: entry.asset,
                    url: entry.url,
                    size: entry.size,
                    sha256: entry.sha256,
                    source: entry.source,
                });
            }
            releases.sort_by(|a, b| a.id.cmp(&b.id));
            Ok(releases)
        };
        let releases = parse_releases(
            (raw.clang.into_iter().map(|entry| (Kind::Clang, entry)))
                .chain(raw.gcc.into_iter().map(|entry| (Kind::Gcc, entry)))
                .collect(),
            false,
        )?;
        let source_releases = parse_releases(
            (raw.gcc_source.into_iter())
                .map(|entry| (Kind::Gcc, entry))
                .collect(),
            true,
        )?;
        let mut prerequisites: Vec<Prerequisite> = Vec::new();
        for entry in raw.prerequisite {
            check(&entry.asset, &entry.asset, &entry.url, &entry.sha256)?;
            if prerequisites.iter().any(|p| p.asset == entry.asset) {
                return Err(invalid(format!("{} is listed twice", entry.asset)));
            }
            prerequisites.push(Prerequisite {
                asset: entry.asset,
                url: entry.url,
                size: entry.size,
                sha256: entry.sha256,
                source: entry.source,
            });
        }
        Ok(Self {
            releases,
            source_releases,
            prerequisites,
            origin: path.map(Path::to_owned),
        })
    }

    /// Every prebuilt release, sorted by kind then version.
    pub fn releases(&self) -> &[Release] {
        &self.releases
    }

    /// Every GCC source release, sorted by version.
    pub fn source_releases(&self) -> &[Release] {
        &self.source_releases
    }

    /// Whether any release of `kind` is known.
    pub fn has_kind(&self, kind: Kind) -> bool {
        self.releases.iter().any(|r| r.id.kind() == kind)
    }

    /// The highest prebuilt release `spec` matches.
    pub fn resolve(&self, spec: &Spec) -> Option<&Release> {
        let id = spec.select(self.releases.iter().map(|r| &r.id))?;
        self.releases.iter().find(|r| &r.id == id)
    }

    /// The highest source release `spec` matches.
    pub fn resolve_source(&self, spec: &Spec) -> Option<&Release> {
        let id = spec.select(self.source_releases.iter().map(|r| &r.id))?;
        self.source_releases.iter().find(|r| &r.id == id)
    }

    /// The library tarball named `asset`, e.g. `gmp-6.1.0.tar.bz2`.
    pub fn prerequisite(&self, asset: &str) -> Option<&Prerequisite> {
        self.prerequisites.iter().find(|p| p.asset == asset)
    }

    /// Where the catalog comes from, for messages.
    pub fn origin(&self) -> String {
        match &self.origin {
            Some(path) => format!("{} (CXVM_CATALOG)", path.display()),
            None => "the catalog built into cxvm".into(),
        }
    }
}

fn is_sha256(hex: &str) -> bool {
    hex.len() == 64 && hex.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

#[cfg(test)]
mod tests {
    use super::*;

    const SHA: &str = "4a5ec53951a584ed36f80240f6fbf8fdd46b4cf6c7ee87cc2d5018dc37caf679";

    fn entry(version: &str) -> String {
        format!(
            "[[clang]]\nversion = \"{version}\"\nasset = \"LLVM-{version}-Linux-X64.tar.xz\"\n\
             url = \"https://example.invalid/{version}.tar.xz\"\nsize = 10\n\
             sha256 = \"{SHA}\"\nsource = \"attestation\"\n"
        )
    }

    fn parse(text: &str) -> Result<Catalog> {
        Catalog::parse(text, Some(Path::new("/c.toml")))
    }

    #[test]
    fn embedded_catalog_is_valid_and_covers_the_promised_releases() {
        let catalog = Catalog::embedded();
        for id in ["clang@19.1.0", "clang@11.1.0", "gcc@15.2.0", "gcc@8.5.0"] {
            let id: ToolchainId = id.parse().unwrap();
            assert!(catalog.releases().iter().any(|r| r.id == id), "{id}");
        }
        assert!(catalog.releases().iter().all(|r| {
            r.url.starts_with(match r.id.kind() {
                Kind::Clang => "https://github.com/llvm/llvm-project/releases/",
                Kind::Gcc => "https://github.com/xpack-dev-tools/gcc-xpack/releases/",
            })
        }));
        assert!(catalog.releases().is_sorted_by(|a, b| a.id < b.id));
    }

    #[test]
    fn embedded_catalog_covers_the_promised_source_releases() {
        let catalog = Catalog::embedded();
        let sources = catalog.source_releases();
        for id in ["gcc@4.8.5", "gcc@6.5.0", "gcc@7.1.0", "gcc@10.5.0"] {
            let id: ToolchainId = id.parse().unwrap();
            assert!(sources.iter().any(|r| r.id == id), "{id}");
        }
        assert!(sources.iter().all(|r| {
            r.id.kind() == Kind::Gcc
                && r.url.starts_with("https://ftpmirror.gnu.org/gnu/gcc/")
                && r.url.ends_with(&r.asset)
        }));
        assert!(sources.is_sorted_by(|a, b| a.id < b.id));
        // What the `contrib/download_prerequisites` of GCC 4.8, 10 and 16 name.
        for asset in [
            "gmp-4.3.2.tar.bz2",
            "mpfr-3.1.6.tar.bz2",
            "mpc-1.3.1.tar.gz",
            "isl-0.24.tar.bz2",
        ] {
            let prerequisite = catalog.prerequisite(asset).expect(asset);
            assert!(
                prerequisite
                    .url
                    .starts_with("https://gcc.gnu.org/pub/gcc/infrastructure/"),
                "{asset}"
            );
        }
        assert_eq!(catalog.prerequisite("cloog-0.18.1.tar.gz"), None);
    }

    #[test]
    fn source_releases_resolve_apart_from_prebuilt_ones() {
        let source = |version: &str| {
            entry(version)
                .replace("[[clang]]", "[[gcc-source]]")
                .replace("LLVM-", "gcc-")
        };
        let prebuilt = entry("13.4.0").replace("[[clang]]", "[[gcc]]");
        let prerequisite = format!(
            "[[prerequisite]]\nasset = \"gmp-6.1.0.tar.bz2\"\n\
             url = \"https://example.invalid/gmp-6.1.0.tar.bz2\"\nsize = 7\n\
             sha256 = \"{SHA}\"\nsource = \"upstream-sha512\"\n"
        );
        let text = [
            prebuilt,
            source("13.4.0"),
            source("13.5.0"),
            source("10.5.0"),
            prerequisite.clone(),
        ]
        .join("\n");
        let catalog = parse(&text).unwrap();
        let resolve = |s: &str| {
            catalog
                .resolve(&s.parse().unwrap())
                .map(|r| r.id.to_string())
        };
        let resolve_source = |s: &str| {
            catalog
                .resolve_source(&s.parse().unwrap())
                .map(|r| r.id.to_string())
        };
        assert_eq!(resolve("gcc@13").as_deref(), Some("gcc@13.4.0"));
        assert_eq!(resolve_source("gcc@13").as_deref(), Some("gcc@13.5.0"));
        assert_eq!(resolve("gcc@10"), None);
        assert_eq!(resolve_source("gcc@10").as_deref(), Some("gcc@10.5.0"));
        assert_eq!(resolve_source("clang@13"), None);
        assert_eq!(catalog.releases().len(), 1);
        assert_eq!(catalog.source_releases().len(), 3);

        let gmp = catalog.prerequisite("gmp-6.1.0.tar.bz2").unwrap();
        assert_eq!(
            gmp.download(),
            Download {
                asset: "gmp-6.1.0.tar.bz2",
                url: "https://example.invalid/gmp-6.1.0.tar.bz2",
                size: 7,
                sha256: SHA,
            }
        );
        assert_eq!(catalog.prerequisite("gmp-6.3.0.tar.bz2"), None);

        for (text, reason) in [
            (
                [source("10.5.0"), source("10.5.0")].join("\n"),
                "gcc@10.5.0 (source) is listed twice",
            ),
            (
                [prerequisite.clone(), prerequisite.clone()].join("\n"),
                "gmp-6.1.0.tar.bz2 is listed twice",
            ),
            (prerequisite.replace("https://", "ftp://"), "not http"),
            (prerequisite.replace("gmp-6", "../gmp-6"), "plain file name"),
        ] {
            let err = parse(&text).unwrap_err().to_string();
            assert!(err.contains(reason), "expected {reason:?} in {err}");
        }
    }

    #[test]
    fn a_catalog_file_may_hold_both_kinds() {
        let gcc = entry("13.3.0").replace("[[clang]]", "[[gcc]]");
        let catalog = parse(&[entry("19.1.0"), gcc, entry("13.3.0")].join("\n")).unwrap();
        let ids: Vec<String> = catalog
            .releases()
            .iter()
            .map(|r| r.id.to_string())
            .collect();
        assert_eq!(ids, ["gcc@13.3.0", "clang@13.3.0", "clang@19.1.0"]);
        assert!(catalog.has_kind(Kind::Gcc));
        let resolved = catalog.resolve(&"gcc@13".parse().unwrap()).unwrap();
        assert_eq!(resolved.id.to_string(), "gcc@13.3.0");
    }

    #[test]
    fn resolves_partial_versions_to_the_highest_release() {
        let catalog =
            parse(&[entry("18.1.8"), entry("19.1.7"), entry("19.1.0")].join("\n")).unwrap();
        let resolve = |s: &str| {
            catalog
                .resolve(&s.parse().unwrap())
                .map(|r| r.id.to_string())
        };
        assert_eq!(resolve("clang@19").as_deref(), Some("clang@19.1.7"));
        assert_eq!(resolve("clang@18.1.8").as_deref(), Some("clang@18.1.8"));
        assert_eq!(resolve("clang@20"), None);
        assert_eq!(resolve("gcc@19"), None);
        assert_eq!(resolve("clang@19-local"), None);
        assert_eq!(resolve("system"), None);
        let ids: Vec<String> = catalog
            .releases()
            .iter()
            .map(|r| r.id.to_string())
            .collect();
        assert_eq!(ids, ["clang@18.1.8", "clang@19.1.0", "clang@19.1.7"]);
    }

    #[test]
    fn rejects_invalid_entries_naming_the_file() {
        for (text, reason) in [
            (entry("19.1"), "not an x.y.z"),
            (entry("19.1.0-local"), "not an x.y.z"),
            ([entry("19.1.0"), entry("19.1.0")].join("\n"), "twice"),
            (
                entry("19.1.0").replace("LLVM-19", "../LLVM-19"),
                "plain file name",
            ),
            (entry("19.1.0").replace("https://", "file://"), "not http"),
            (
                entry("19.1.0").replace(SHA, &SHA.to_uppercase()),
                "64 lowercase hex",
            ),
            (
                entry("19.1.0").replace("size = 10", "size = 10\nextra = 1"),
                "unknown field",
            ),
            ("[[rust]]\n".into(), "unknown field"),
        ] {
            let err = parse(&text).unwrap_err().to_string();
            assert!(err.contains("/c.toml"), "{err}");
            assert!(err.contains(reason), "expected {reason:?} in {err}");
            assert!(err.contains("CXVM_CATALOG"), "{err}");
        }
    }

    #[test]
    fn loads_a_catalog_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("c.toml");
        std::fs::write(&path, entry("19.1.0")).unwrap();
        let catalog = Catalog::load(Some(&path)).unwrap();
        assert_eq!(catalog.releases().len(), 1);
        assert!(catalog.origin().contains("CXVM_CATALOG"));
        let err = Catalog::load(Some(&dir.path().join("missing.toml"))).unwrap_err();
        assert!(err.to_string().contains("CXVM_CATALOG"), "{err}");
    }
}
